/**
 * PWA registration. Workbox is generated by vite-plugin-pwa.
 * Falls back to no-op in non-browser contexts.
 */
export function registerServiceWorker(): void {
  if (typeof window === 'undefined') {
    return;
  }

  if ('serviceWorker' in navigator && import.meta.env.PROD) {
    // Dynamic import so it doesn't break SSR/test
    void import('virtual:pwa-register')
      .then(({ registerSW }) => {
        registerSW({
          immediate: true,
          onNeedRefresh() {
            // surfaced via Toaster
            window.dispatchEvent(new CustomEvent('afya:pwa-update-available'));
          },
          onOfflineReady() {
            window.dispatchEvent(new CustomEvent('afya:pwa-offline-ready'));
          },
        });
      })
      .catch(() => {
        // PWA plugin not present in dev — ignore
      });
  }
}